import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.BL79I5mR.js";const u=JSON.parse('{"title":"CaSS Installation","description":"","frontmatter":{},"headers":[],"relativePath":"dev/cass-installation/index.md","filePath":"dev/cass-installation/README.md"}'),o={name:"dev/cass-installation/index.md"};function n(r,e,l,c,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="cass-installation" tabindex="-1">CaSS Installation <a class="header-anchor" href="#cass-installation" aria-label="Permalink to &quot;CaSS Installation&quot;">​</a></h1><p>This is the installation guide for a CaSS instance. If you&#39;re just looking to work with an existing CaSS instance, you may be looking for the CaSS Library. See the <a href="/docs/dev/links-and-references.html">Links</a> section for more information.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li>4 GB of ram (can work with 2 GB with additional configuration) <ul><li>ElasticSearch 7: 2 GB (can be reduced to 1 GB)</li></ul></li><li>At least 8 GB of hard drive space.</li></ul><h2 id="cass-version-requirements" tabindex="-1">CaSS Version Requirements <a class="header-anchor" href="#cass-version-requirements" aria-label="Permalink to &quot;CaSS Version Requirements&quot;">​</a></h2><p>Minimum CaSS version selection for inclusion of CaSS Authoring Tools should be <strong>1.3</strong></p><h2 id="cat-cass-installation" tabindex="-1">CAT/CaSS Installation <a class="header-anchor" href="#cat-cass-installation" aria-label="Permalink to &quot;CAT/CaSS Installation&quot;">​</a></h2><h3 id="linux-debian-ubuntu-amazon-and-other-fedora-derivatives" tabindex="-1">Linux (Debian, Ubuntu, Amazon and other Fedora derivatives) <a class="header-anchor" href="#linux-debian-ubuntu-amazon-and-other-fedora-derivatives" aria-label="Permalink to &quot;Linux (Debian, Ubuntu, Amazon and other Fedora derivatives)&quot;">​</a></h3><p>CaSS can be installed on linux through our Bash install script.</p><p>Install and Upgrade</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/cassproject/CASS/master/scripts/cassInstall.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cassInstall.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cassInstall.sh</span></span></code></pre></div><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><p>Images for CASS are kept in Docker Hub under <a href="https://hub.docker.com/r/cassproject/cass" target="_blank" rel="noreferrer">cassproject/cass</a>.</p><p>The following command will run the CaSS Standalone server with an interactive prompt and expose it on port 80 on the local machine.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p80:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cassproject/cass</span></span></code></pre></div><p>Additionally, if you wish to use docker-compose or some other means of deploying CaSS in a constellation of servers, see <a href="https://github.com/cassproject/CASS/blob/master/docker-compose.yml" target="_blank" rel="noreferrer">this docker-compose file</a>.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Windows installation uses <a href="https://chocolatey.org/" target="_blank" rel="noreferrer">Chocolatey</a> as a package manager. Chocolatey will be used to install all required CASS dependencies (maven, git, and elasticsearch).</p><p>If you would like to install these packages by hand or using another tool, please feel free.</p><p><a href="https://chocolatey.org/packages/cass" target="_blank" rel="noreferrer">CASS Package on Chocolatey</a></p><h3 id="once" tabindex="-1">Once <a class="header-anchor" href="#once" aria-label="Permalink to &quot;Once&quot;">​</a></h3><p>From an elevated powershell:</p><div class="language-batch vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Set-ExecutionPolicy Bypass -Scope Process -Force; [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor 3072; iex ((New-Object System.Net.WebClient).DownloadString(&#39;https://community.chocolatey.org/install.ps1&#39;))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refreshenv</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">choco install -y cass</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refreshenv</span></span></code></pre></div><p>Go to services, start <code>elasticsearch-service-x64</code> and set it to start automatically.</p><h3 id="install-upgrade" tabindex="-1">Install/Upgrade <a class="header-anchor" href="#install-upgrade" aria-label="Permalink to &quot;Install/Upgrade&quot;">​</a></h3><p>Before upgrading, copy out the etc folder from the root directory of the CaSS installation. From an elevated command line:</p><div class="language-batch vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">choco install -y cass</span></span></code></pre></div><p>Then copy the etc folder back in.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ul><li>Set up a <strong>DNS endpoint</strong></li><li>Set up an <strong>HTTPS certificate</strong></li><li>Set up <a href="https://weblogs.asp.net/owscott/creating-a-reverse-proxy-with-url-rewrite-for-iis" target="_blank" rel="noreferrer">IIS Reverse Proxy</a><ul><li>Reverse Proxy Endpoint: <code>https://&lt;your cass domain&gt;/ -&gt; http://localhost:8080/cass/</code></li></ul></li><li>In your firewall, deny access to ports <code>9200</code> and <code>8080</code> to all machines except localhost.</li></ul><h2 id="post-installation-checklist" tabindex="-1">Post-Installation Checklist <a class="header-anchor" href="#post-installation-checklist" aria-label="Permalink to &quot;Post-Installation Checklist&quot;">​</a></h2><ol><li>Ensure API is started and reachable through a desired endpoint</li><li>(e.g. <code>http://cass.&lt;your_organization&gt;.org/api/custom/</code>).</li><li>Note that all objects created will use this endpoint in their permanent locator, so make sure!</li><li>Ensure Website is reachable through a desired endpoint</li><li>(e.g. <code>http://cass.&lt;your_organization&gt;.org/</code>).</li><li>CASS attempts to auto-detect the endpoint for the server automatically. XSS or obscure endpoints may require additional configuration.</li><li>Set PM2 logs to rotate with the <code>npm run rotatelogs</code> command. On Windows machines, we have found that it works better to change the rotatelogs command in the package.json file to <code>pm2 install @jessety/pm2-logrotate</code> before running the npm command.</li><li>To get the process to restart when your Linux machine restarts, run <code>npm run pm2startup</code>, run the command the process tells you to, and run <code>npm run pm2save</code>. For Windows, an additional library is needed to configure this. We followed the instructions here: <a href="https://stackoverflow.com/a/42770772" target="_blank" rel="noreferrer">https://stackoverflow.com/a/42770772</a></li></ol><h2 id="testing-upgrade-and-installation-faq" tabindex="-1">Testing, upgrade, and installation FAQ <a class="header-anchor" href="#testing-upgrade-and-installation-faq" aria-label="Permalink to &quot;Testing, upgrade, and installation FAQ&quot;">​</a></h2><ol><li>Most errors will occur due to a lack of connectivity with the appropriate endpoint. Use the Browser Development Tools to ensure that requests are going to the correct location.</li><li>Check to ensure the environment variable <code>CASS_LOOPBACK</code> is set to the endpoint of the server.</li><li>Apache requires proxy_http to function. If Apache fails to start up, the proxy_http module may not be enabled. In HTTPD, this is called <code>mod_proxy_http</code>.</li><li>The installer will not modify a current install of the Apache/HTTPD Web Server if proxy settings are being used (even from a previous install).</li><li>When upgrading from 0.1.0 -- If you get the error <code>HTTP Status 404 - /cass-0.0.1/</code></li><li>Alter the apache conf files to use ProxyPass / <code>http://localhost:8080/cass/</code>, not ProxyPass / <code>http://localhost:8080/cass-0.0.1/</code></li><li>After an upgrade, database incompatibilities may occur. You may export and import data before upgrades using the following web services: <ul><li><code>http://&lt;endpoint&gt;/skyrepo/util/backup?secret=[contents of skyId.secret in etc folder]</code></li><li><code>http://&lt;endpoint&gt;/skyrepo/util/restore?secret=[contents of skyId.secret in etc folder]</code></li></ul></li><li>If you are upgrading ElasticSearch from version 5 to 7, you&#39;ll need to first upgrade to 6 and start CaSS. Keep an eye on the logs, and after the data has finished reindexing, you can upgrade to 7.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ol><li><strong>Is ElasticSearch running?</strong><ul><li>If not, start it manually and ensure the service is configured to start automatically on boot.</li></ul></li><li><strong>Is PM2 running?</strong><ul><li>If not, start it manually and ensure the service is configured to start automatically on boot.</li></ul></li><li><strong>Can you access <code>http://&lt;server ip&gt;:8080/cass/</code>?</strong><ul><li>Make sure there are no conflicts on port 8080.</li><li>Verify that PM2 is running.</li></ul></li><li><strong>Can you access <code>http://&lt;server ip&gt;:8080/cass/api/</code> with a response “Service does not exist”?</strong><ul><li>If the request hangs, ensure ElasticSearch is running and that it started without error (check the logs).</li></ul></li><li><strong>Can you access <code>http://&lt;server ip&gt;:8080/cass/api/data?q=*</code> and receive a valid response (empty list or data array depending on the data in the system)?</strong><ul><li>If the request hangs, ensure ElasticSearch is running and that it started without error (check the logs).</li></ul></li><li><strong>Access your local CASS installation via browser <code>http://&lt;server ip&gt;:8080/cass/</code>, create a new user, and attempt to login.</strong><ul><li>Did the login complete?</li><li>Did the login icon in the left sidebar change to display your initials?</li><li>Did you gain new capabilities? (Assertions, Configuration -&gt; Users and Groups)</li><li>If not, repeat the operations with browser developer tools enabled. Watch the network stream and ensure the ‘login’, ‘create’, and ‘commit’ requests and responses are occurring without incident.</li></ul></li><li><strong>Create a framework.</strong><ul><li>Did it appear on the screen? <ul><li>If not, repeat the operation with browser developer tools enabled. Watch the network stream and ensure the framework creation POST occurred without incident.</li></ul></li></ul></li><li><strong>Create a competency in the framework.</strong><ul><li>Did it appear in the framework? <ul><li>If not, repeat the operation with browser developer tools enabled. Watch the network stream and ensure the competency creation POST occurred without incident.</li></ul></li><li>Delete the competency and framework.</li></ul></li><li><strong>Can you access <code>https://&lt;server endpoint&gt;/</code> and view the website?</strong><ul><li>If not, can you access <code>http://&lt;server endpoint&gt;/</code> (http vs. https) and view the website? <ul><li>If so, verify the reverse proxy settings are applied to the HTTPS configuration.</li><li>If not, ensure the Apache2 server (or IIS) is working correctly (check the logs, debug the reverse proxy, etc.).</li></ul></li></ul></li><li><strong>Can you access <code>https://&lt;server endpoint&gt;/api/ </code>and get “Service does not exist”?</strong><ul><li>If not, ensure the Apache2 server (or IIS) is working correctly (check the logs, debug the reverse proxy, etc.).</li></ul></li></ol>`,36)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
